// Handle Ollama response or provide fallback
const input = $input.first();

if (input.json && input.json.message && input.json.message.content) {
  // Success - parse the AI response
  try {
    const content = input.json.message.content;
    const taskData = JSON.parse(content);

    return {
      json: {
        title: taskData.title,
        description: taskData.description,
        difficulty_level: taskData.difficulty_level,
        category: taskData.category,
        estimated_duration: Array.isArray(taskData.estimated_duration) ? taskData.estimated_duration[0] : taskData.estimated_duration,
        learning_objectives: Array.isArray(taskData.learning_objectives) ? taskData.learning_objectives : [taskData.learning_objectives],
        generated_by_ai: true
      }
    };
  } catch (error) {
    // Fallback if parsing fails
    return {
      json: {
        title: "Build a REST API with Express.js",
        description: "Create a simple REST API using Node.js and Express. Include endpoints for CRUD operations on a resource of your choice. Implement proper error handling and input validation.",
        difficulty_level: "intermediate",
        category: "Backend Development",
        estimated_duration: 120,
        learning_objectives: ["Learn Express.js framework", "Understand REST principles", "Practice API design"],
        generated_by_ai: false
      }
    };
  }
} else {
  // Fallback if Ollama request failed
  return {
    json: {
      title: "Build a REST API with Express.js",
      description: "Create a simple REST API using Node.js and Express. Include endpoints for CRUD operations on a resource of your choice. Implement proper error handling and input validation.",
      difficulty_level: "intermediate",
      category: "Backend Development",
      estimated_duration: 120,
      learning_objectives: ["Learn Express.js framework", "Understand REST principles", "Practice API design"],
      generated_by_ai: false
    }
  };
}

// Format data for PostgreSQL insertion
const taskData = $input.first().json;

// Ensure learning_objectives is properly formatted as JSON string for JSONB
const formattedData = {
  title: taskData.title,
  description: taskData.description,
  difficulty_level: taskData.difficulty_level,
  category: taskData.category,
  estimated_duration: taskData.estimated_duration,
  learning_objectives: JSON.stringify(taskData.learning_objectives),
  generated_by_ai: taskData.generated_by_ai
};

return { json: formattedData };

// Get the saved task and assign to students
const savedTask = $input.first().json;
const taskId = savedTask.id;

// Get Spring 2024 students
const students = [
  { id: 1, name: 'Alice Johnson', email: 'alice@example.com' },
  { id: 2, name: 'Bob Smith', email: 'bob@example.com' },
  { id: 3, name: 'Charlie Brown', email: 'charlie@example.com' }
];

// Create summary
const summary = {
  task_id: taskId,
  task_title: savedTask.title,
  assigned_students: students.length,
  students: students,
  message: `Task '${savedTask.title}' has been created and assigned to ${students.length} students in Spring 2024 cohort.`
};

return { json: summary };
